import {normalizeRect,detectCandidates,validatePixels,sanitizePNG} from './core.js';
import {makeSample} from './sample.js';
const $=id=>document.getElementById(id), color=[36,43,42,255];
let source, candidates=[], manual=[], history=[], worker, scanned=false, busy=false, drawing=false, dragStart, draftRect, version=0, verified, loadToken=0, currentOCR=0;
const canvas=$('canvas'),ctx=canvas.getContext('2d');
function say(t){$('status').textContent=t;}
function invalidate(){version++;if(verified?.url)URL.revokeObjectURL(verified.url);verified=undefined;$('result').hidden=true;$('visual-check').checked=false;updateControls();}
function allMasks(){return [...candidates.filter(x=>x.decision==='cover').map(x=>x.rect),...manual.map(x=>x.rect)];}
function updateControls(){const pending=candidates.filter(x=>!x.decision).length;$('visual-check').disabled=busy;$('file').disabled=busy;$('reset').disabled=busy;$('sample').disabled=busy;$('build').disabled=busy||!source||pending>0||allMasks().length===0||!$('visual-check').checked;$('scan').disabled=busy||!source;$('undo').disabled=busy||!history.length;$('draw').disabled=busy||!source;$('add-rect').disabled=busy||!source;$('download-png').disabled=!verified;$('download-note').disabled=!verified;$('mask-count').textContent=allMasks().length+' '+(allMasks().length===1?'cover':'covers');$('build-help').textContent=busy?'Working locally…':pending?pending+' suggestion'+(pending===1?'':'s')+(pending===1?' still needs a decision.':' still need a decision.'):allMasks().length===0?'Add at least one cover before inspecting an export.':!$('visual-check').checked?'Check the full image, then confirm above.':'Ready to build the file and inspect its covered pixels.';$('review-step').className=source?'active':'';$('export-step').className=verified?'done':'';}
function render(){if(!source)return;canvas.width=source.width;canvas.height=source.height;ctx.drawImage(source,0,0);ctx.fillStyle='rgb('+color.slice(0,3).join(',')+')';for(const r of allMasks())ctx.fillRect(r.x,r.y,r.w,r.h);
 const factor=source.width/(canvas.getBoundingClientRect().width||source.width);ctx.lineWidth=2*factor;
 for(const c of candidates.filter(x=>!x.decision)){ctx.strokeStyle='#b63e2b';ctx.setLineDash([5*factor,3*factor]);ctx.strokeRect(c.rect.x,c.rect.y,c.rect.w,c.rect.h);}
 ctx.setLineDash([]);if(draftRect){ctx.fillStyle='#242b2a80';ctx.fillRect(draftRect.x,draftRect.y,draftRect.w,draftRect.h);ctx.strokeStyle='#ffffff';ctx.strokeRect(draftRect.x,draftRect.y,draftRect.w,draftRect.h);}updateControls();}
function renderList(){const list=$('candidates');list.replaceChildren();if(!candidates.length){const empty=document.createElement('div');empty.className='empty-note';const p=document.createElement('p');p.textContent=scanned?'No email or phone candidates found. Check the image for missed details.':'Suggestions will appear here. You can also draw a cover directly.';empty.append(p);list.append(empty);}
 candidates.forEach((c,i)=>{const el=document.createElement('div');el.className='candidate';const top=document.createElement('div');top.className='candidate-top';const title=document.createElement('span');title.textContent=(c.kind==='email'?'Email':'Phone')+' '+(i+1);const tag=document.createElement('small');tag.textContent=c.decision==='cover'?'Covered':c.decision==='keep'?'Kept intentionally':'Review';top.append(title,tag);const loc=document.createElement('div');loc.className='candidate-location';const box=document.createElement('span');box.textContent='x '+c.rect.x+' · y '+c.rect.y+' · '+c.rect.w+' × '+c.rect.h+' px';loc.append(box);const actions=document.createElement('div');actions.className='candidate-actions';for(const [decision,label] of [['cover','Cover'],['keep','Keep visible']]){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',label+' '+title.textContent);b.className=(decision==='keep'?'keep ':'')+(c.decision===decision?'selected':'');b.setAttribute('aria-pressed',String(c.decision===decision));b.disabled=busy;b.onclick=()=>{if(busy)return;history.push({kind:'candidate',id:c.id,previous:c.decision});c.decision=decision;invalidate();renderList();render();say(decision==='cover'?'Cover added.':'Suggestion intentionally kept visible.');};actions.append(b);}el.append(top,loc,actions);list.append(el);});
 const m=$('manual-list');m.replaceChildren();manual.forEach((entry,i)=>{const row=document.createElement('div');row.className='manual-cover';const text=document.createElement('span');text.textContent='Hand cover '+(i+1)+' · '+entry.rect.w+' × '+entry.rect.h+' px';const b=document.createElement('button');b.textContent='Remove';b.setAttribute('aria-label','Remove hand cover '+(i+1));b.disabled=busy;b.onclick=()=>{if(busy)return;history.push({kind:'remove',entry,index:i});manual.splice(i,1);invalidate();renderList();render();};row.append(text,b);m.append(row);});updateControls();}
function setSource(c,title,origin){if(source&&source!==c){source.width=1;source.height=1;}source=c;candidates=[];manual=[];history=[];scanned=false;busy=false;draftRect=undefined;dragStart=undefined;drawing=false;canvas.classList.remove('drawing');$('draw').setAttribute('aria-pressed','false');$('draw-hint').hidden=true;$('scan-progress').hidden=true;$('scan-status').textContent='Local OCR. Small or non-English text may be missed.';$('image-title').textContent=title;$('image-origin').textContent=origin;$('dimensions').textContent=c.width+' × '+c.height+' px';invalidate();renderList();render();say('');}
function sample(){loadToken++;setSource(makeSample(),'Sample receipt','Fictional sample · example.com addresses');}
function dims(b){const v=new DataView(b.buffer,b.byteOffset,b.byteLength);if(b.length>=24&&b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71)return [v.getUint32(16),v.getUint32(20)];if(b[0]===255&&b[1]===216){let p=2;while(p+4<=b.length){if(b[p]!==255)throw Error('Invalid JPEG segment.');const type=b[p+1];p+=2;if(type===217||type===218)break;if(type===1||(type>=208&&type<=215))continue;const length=v.getUint16(p);if(length<2||p+length>b.length)throw Error('Invalid JPEG segment.');if([192,193,194,195,197,198,199,201,202,203,205,206,207].includes(type)){if(length<7)break;return [v.getUint16(p+5),v.getUint16(p+3)];}p+=length;}throw Error('JPEG dimensions could not be read.');}if(b.length>=30&&String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP'){const t=String.fromCharCode(...b.slice(12,16));if(t==='VP8X')return [1+b[24]+b[25]*256+b[26]*65536,1+b[27]+b[28]*256+b[29]*65536];if(t==='VP8 '&&b[23]===157&&b[24]===1&&b[25]===42)return [v.getUint16(26,true)&16383,v.getUint16(28,true)&16383];if(t==='VP8L'&&b[20]===47){const n=v.getUint32(21,true);return [(n&16383)+1,((n>>>14)&16383)+1];}}throw Error('Use a supported PNG, JPEG or WebP image.');}
$('file').onchange=async e=>{const f=e.target.files?.[0];if(!f||busy)return;const token=++loadToken;cancelDrag();busy=true;updateControls();try{if(f.size>12*1024*1024)throw Error('Choose an image under 12 MB.');const bytes=new Uint8Array(await f.arrayBuffer()),[w,h]=dims(bytes);if(w<=0||h<=0||w*h>12e6||w>16000||h>16000)throw Error('Choose an image up to 12 million pixels and 16,000 px per edge.');const bitmap=await createImageBitmap(new Blob([bytes]));if(token!==loadToken){bitmap.close();return;}if(bitmap.width*bitmap.height>12e6){bitmap.close();throw Error('The decoded image is too large.');}const c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;c.getContext('2d').drawImage(bitmap,0,0);bitmap.close();setSource(c,'Your image','Local image · not uploaded');}catch(err){if(token===loadToken)say(err.message);}finally{if(token===loadToken){busy=false;updateControls();}e.target.value='';}};
$('sample').onclick=()=>{if(!busy)sample();};$('reset').onclick=()=>{if(!busy)sample();};
$('draw').onclick=()=>{drawing=!drawing;canvas.classList.toggle('drawing',drawing);$('draw').setAttribute('aria-pressed',String(drawing));$('draw-hint').hidden=!drawing;};
function cancelDrag(){dragStart=undefined;draftRect=undefined;render();}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*source.width/r.width,y:(e.clientY-r.top)*source.height/r.height};}
canvas.onpointerdown=e=>{if(!drawing||busy||dragStart||e.button!==0)return;e.preventDefault();dragStart=point(e);canvas.setPointerCapture(e.pointerId);};
canvas.onpointermove=e=>{if(!dragStart||busy)return;const p=point(e);draftRect=normalizeRect({x:Math.min(p.x,dragStart.x),y:Math.min(p.y,dragStart.y),w:Math.abs(p.x-dragStart.x),h:Math.abs(p.y-dragStart.y)},source.width,source.height);render();};
canvas.onpointerup=e=>{if(busy){cancelDrag();return;}if(!dragStart)return;const p=point(e);try{const r=normalizeRect({x:Math.min(p.x,dragStart.x),y:Math.min(p.y,dragStart.y),w:Math.abs(p.x-dragStart.x),h:Math.abs(p.y-dragStart.y)},source.width,source.height);if(r?.w>=2&&r?.h>=2)addManual(r);}catch(err){say(err.message);}dragStart=undefined;draftRect=undefined;render();};
canvas.onpointercancel=()=>{dragStart=undefined;draftRect=undefined;render();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){dragStart=undefined;draftRect=undefined;dragStart=undefined;drawing=false;canvas.classList.remove('drawing');$('draw').setAttribute('aria-pressed','false');$('draw-hint').hidden=true;render();}});
function addManual(r){if(busy)return;if(!r||r.w<1||r.h<1)throw Error('The cover must include at least one pixel.');const entry={id:crypto.randomUUID(),rect:r};history.push({kind:'add',id:entry.id});manual.push(entry);invalidate();renderList();render();say('Hand cover added.');}
$('add-rect').onclick=()=>{try{const v=['x','y','w','h'].map(k=>Number($('rect-'+k).value));if(!v.every(Number.isFinite)||v[2]<=0||v[3]<=0)throw Error('Enter positive width and height.');addManual(normalizeRect({x:v[0],y:v[1],w:v[2],h:v[3]},source.width,source.height));}catch(err){say(err.message);}};
$('undo').onclick=()=>{const a=history.pop();if(!a)return;if(a.kind==='add')manual=manual.filter(x=>x.id!==a.id);if(a.kind==='remove')manual.splice(a.index,0,a.entry);if(a.kind==='candidate'){const c=candidates.find(c=>c.id===a.id);if(c)c.decision=a.previous;}invalidate();renderList();render();say('Last review change undone.');};
$('visual-check').onchange=updateControls;
$('scan').onclick=async()=>{if(busy)return;cancelDrag();invalidate();const mine=version;currentOCR=mine;busy=true;$('scan-progress').hidden=false;$('scan-status').textContent='Starting the local OCR worker…';updateControls();renderList();say('');try{if(!window.Tesseract)throw Error('OCR assets unavailable. You can still add covers manually.');worker??=await Tesseract.createWorker('eng',1,{workerPath:new URL('./assets/ocr/worker.min.js',location.href).href,corePath:new URL('./assets/ocr/core',location.href).href,langPath:new URL('./assets/ocr/lang',location.href).href,workerBlobURL:false,gzip:true,cacheMethod:'none',logger:m=>{if(version!==currentOCR)return;const p=Math.max(0,Math.min(1,m.progress||0));$('progress-bar').style.width=p*100+'%';$('scan-status').textContent=(m.status||'Reading image')+(m.status==='recognizing text'?' · '+Math.round(p*100)+'%':'');}});const result=await worker.recognize(source,{}, {blocks:true,text:true});if(version!==mine)return;const prior=candidates;candidates=detectCandidates(result.data.blocks||[],source.width,source.height).map(c=>({...c,decision:prior.find(x=>x.kind===c.kind&&JSON.stringify(x.rect)===JSON.stringify(c.rect))?.decision}));scanned=true;$('scan-status').textContent=candidates.length+' contact suggestion'+(candidates.length===1?'':'s')+' found. Review them below.';say('OCR finished on this device. Check for missed details too.');}catch(err){if(version!==mine)return;$('scan-status').textContent='OCR unavailable. Use the hand-cover tools and inspect the full image.';say('The OCR check did not complete. Manual covers remain available.');if(worker){await worker.terminate().catch(()=>{});worker=undefined;}}finally{if(version===mine){busy=false;$('scan-progress').hidden=true;renderList();render();}}};
function blobFor(c){return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('PNG creation failed.')),'image/png'));}
$('build').onclick=async()=>{if($('build').disabled)return;cancelDrag();busy=true;const mine=version,masks=allMasks().map(x=>({...x}));updateControls();say('Building a fresh PNG and checking its decoded pixels…');try{const out=document.createElement('canvas');out.width=source.width;out.height=source.height;const g=out.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,out.width,out.height);g.drawImage(source,0,0);g.fillStyle='rgb('+color.slice(0,3).join(',')+')';for(const r of masks)g.fillRect(r.x,r.y,r.w,r.h);const original=await blobFor(out);const inspected=sanitizePNG(new Uint8Array(await original.arrayBuffer()));const blob=new Blob([inspected.bytes],{type:'image/png'}),decoded=await createImageBitmap(blob);if(decoded.width!==source.width||decoded.height!==source.height){decoded.close();throw Error('Export dimensions changed.');}const checkCanvas=document.createElement('canvas');checkCanvas.width=decoded.width;checkCanvas.height=decoded.height;const cg=checkCanvas.getContext('2d');cg.drawImage(decoded,0,0);decoded.close();const check=validatePixels(cg.getImageData(0,0,checkCanvas.width,checkCanvas.height).data,checkCanvas.width,checkCanvas.height,masks,color);if(!check.ok)throw Error('Selected cover pixels did not pass inspection.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',inspected.bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(version!==mine)return;const note={format:'ShareProof inspection note v1',created_at:new Date().toISOString(),output:{mime:'image/png',width:source.width,height:source.height,bytes:blob.size,sha256:hash},review:{local_english_ocr_completed:scanned,suggested_count:candidates.length,intentionally_kept_count:candidates.filter(x=>x.decision==='keep').length,manual_visual_review_confirmed:true,selected_cover_count:masks.length},inspection:{selected_regions:masks,all_selected_pixels_solid_opaque:true,checked_pixels:check.checkedPixels,retained_png_chunks:inspected.retained,removed_png_chunks:inspected.removed},scope:'Only selected cover pixels and PNG chunk contents were checked. OCR may miss private details; this is not an all-image privacy certification.'};verified={blob,note,url:URL.createObjectURL(blob)};$('export-image').src=verified.url;$('pixel-result').textContent=check.checkedPixels.toLocaleString()+' checked';$('chunk-result').textContent=[...new Set(inspected.retained)].join(' · ');$('byte-result').textContent=(blob.size/1024).toFixed(1)+' KB';$('hash-result').textContent=hash;$('result-summary').textContent=masks.length+' selected area'+(masks.length===1?' is':'s are')+' solid and opaque in the decoded export.';$('result').hidden=false;say('The export passed the selected-area check. Download this exact PNG.');$('result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}catch(err){if(version!==mine)return;say('Export stopped: '+err.message);$('result').hidden=true;}finally{if(version===mine){busy=false;updateControls();renderList();}}};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('download-png').onclick=()=>{if(verified)download(verified.blob,'shareproof-reviewed.png');};$('download-note').onclick=()=>{if(verified)download(new Blob([JSON.stringify(verified.note,null,2)],{type:'application/json'}),'shareproof-inspection.json');};
$('method-button').onclick=()=>$('method').showModal();$('close-method').onclick=()=>$('method').close();
window.addEventListener('beforeunload',()=>{worker?.terminate();if(verified?.url)URL.revokeObjectURL(verified.url);});sample();
